#[test]
fn omp_real_binary_capacity_observation() {
    const CONNECTION_BOUND: usize = 2;
    const PARTIAL_DEADLINE_MS: u64 = 5_000;
    const WRITE_DEADLINE_MS: u64 = 500;
    let status = StatusServer::start();
    let mut fixture = Fixture::new(BASIC_PASS_COMMAND, true);
    fixture.config.read_timeout_ms = PARTIAL_DEADLINE_MS;
    fixture.config.write_timeout_ms = WRITE_DEADLINE_MS;
    fixture.config.maximum_connections = CONNECTION_BOUND;
    let mut child = fixture.spawn_binary(&status.origin());
    let observed = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut partials = Vec::new();
        for _ in 0..CONNECTION_BOUND {
            let mut stream = connect(fixture.config.listen_address);
            stream.write_all(b"POST /github/webhook HTTP/1.1\r\nHost: localhost\r\n").unwrap();
            partials.push(stream);
        }
        let payload = body(&fixture.source_revision);
        let delivery = headers(&payload, DELIVERY_BASE);
        let capacity = raw_request(fixture.config.listen_address, &signed_request(&payload, &delivery));
        assert!(capacity.starts_with("HTTP/1.1 503"), "capacity premise was not observed: {capacity}");
        let state = fixture.job_state();
        assert_eq!(state.dispatches, 0);
        assert_eq!(state.job_runs, 0);
        drop(state);
        assert!(status.records().is_empty());
        for stream in &mut partials {
            stream.set_read_timeout(Some(TEST_TIMEOUT)).unwrap();
            let mut response = String::new();
            stream.read_to_string(&mut response).unwrap();
            assert!(response.starts_with("HTTP/1.1 408"), "actual partial deadline: {response}");
        }
        drop(partials);
        let response = fixture.send(DELIVERY_BASE);
        assert!(!response_duplicate(&response));
        let run = fixture.run_identity(&response);
        let record = fixture.wait_for_terminal(&run);
        assert_eq!(record.outcome().unwrap(), Outcome::Success);
        let state = fixture.job_state();
        assert_eq!(state.dispatches, 1);
        assert_eq!(state.job_runs, 1);
        drop(state);
        assert_eq!(status.records().len(), 2);
        println!("observed github standalone binary: 2 actual partial connections at bound; capacity503/no job/status effect; both partial408; same delivery202/nonduplicate; exactly1 dispatch and job");
    }));
    fixture.stop_binary(&mut child);
    if let Err(error) = observed { std::panic::resume_unwind(error); }
}

